CREATE TABLE project(id TEXT PRIMARY KEY, recommended_task TEXT NOT NULL, source_commit TEXT NOT NULL);
CREATE TABLE protocol(project_id TEXT REFERENCES project, version INTEGER, plan TEXT NOT NULL, continuation TEXT NOT NULL, PRIMARY KEY(project_id,version));
CREATE TABLE task(created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),project_id TEXT, task_id TEXT, title TEXT NOT NULL, imported_status TEXT NOT NULL,current_status TEXT, protocol_version INTEGER NOT NULL, legacy_json TEXT NOT NULL,
 PRIMARY KEY(project_id,task_id), FOREIGN KEY(project_id,protocol_version) REFERENCES protocol);
CREATE TABLE checkpoint(created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),project_id TEXT,task_id TEXT,revision INTEGER, request_key TEXT NOT NULL, cursor_json TEXT, next_action TEXT NOT NULL, PRIMARY KEY(project_id,task_id,revision), UNIQUE(project_id,task_id,request_key), FOREIGN KEY(project_id,task_id) REFERENCES task);
CREATE TABLE resource(created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),observed_at TEXT,project_id TEXT REFERENCES project,id TEXT,kind TEXT NOT NULL,title TEXT NOT NULL,payload_json TEXT NOT NULL, PRIMARY KEY(project_id,id));
CREATE TABLE observation(created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),observed_at TEXT,project_id TEXT,legacy_id TEXT,resource_id TEXT NOT NULL,source_file TEXT NOT NULL,raw_json TEXT NOT NULL,PRIMARY KEY(project_id,legacy_id),FOREIGN KEY(project_id,resource_id) REFERENCES resource);
CREATE TABLE source(url TEXT PRIMARY KEY);
CREATE TABLE evidence(created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),observed_at TEXT,id INTEGER PRIMARY KEY,project_id TEXT,resource_id TEXT,url TEXT NOT NULL REFERENCES source, origin TEXT NOT NULL, detail_json TEXT NOT NULL,FOREIGN KEY(project_id,resource_id) REFERENCES resource);
CREATE INDEX evidence_by_resource ON evidence(project_id,resource_id);
CREATE TABLE scan_item(created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),observed_at TEXT,project_id TEXT,task_id TEXT,ordinal INTEGER,external_id TEXT NOT NULL,decision TEXT NOT NULL,resource_id TEXT,payload_json TEXT NOT NULL,PRIMARY KEY(project_id,task_id,ordinal),UNIQUE(project_id,task_id,external_id),FOREIGN KEY(project_id,task_id) REFERENCES task, FOREIGN KEY(project_id,resource_id) REFERENCES resource);
CREATE TABLE source_file(project_id TEXT REFERENCES project,path TEXT,sha256 TEXT NOT NULL,content BLOB NOT NULL,PRIMARY KEY(project_id,path));
CREATE VIEW resume AS SELECT t.project_id,t.task_id,t.title,t.imported_status,COALESCE(t.current_status,t.imported_status) AS status,t.protocol_version,c.revision,c.cursor_json,c.next_action,(p.recommended_task=t.task_id) AS recommended FROM task t JOIN project p ON p.id=t.project_id JOIN checkpoint c USING(project_id,task_id) WHERE c.revision=(SELECT MAX(k.revision) FROM checkpoint k WHERE k.project_id=t.project_id AND k.task_id=t.task_id);

